import { NextRequest, NextResponse } from 'next/server'
import { createAdminClient } from '@/lib/supabase/server'

// 🔍 数据库状态查看API
export async function GET(request: NextRequest) {
  try {
    console.log('🔍 开始查看数据库状态...')

    const supabase = createAdminClient()
    const results: any = {
      timestamp: new Date().toISOString(),
      tables: {},
      summary: {}
    }

    // 检查各个表的数据统计
    const tables = [
      'users',
      'payment_orders', 
      'credit_transactions',
      'subscriptions',
      'payment_configs',
      'generations'
    ]

    for (const tableName of tables) {
      try {
        console.log(`🔍 检查表: ${tableName}`)

        // 获取表的记录数量
        const { count, error: countError } = await supabase
          .from(tableName)
          .select('*', { count: 'exact', head: true })

        if (countError) {
          console.log(`❌ 表 ${tableName} 查询失败:`, countError.message)
          results.tables[tableName] = {
            exists: false,
            error: countError.message,
            count: 0
          }
        } else {
          console.log(`✅ 表 ${tableName} 存在，记录数: ${count}`)

          // 获取最近的几条记录作为示例
          const { data: sampleData, error: sampleError } = await supabase
            .from(tableName)
            .select('*')
            .limit(3)
            .order('created_at', { ascending: false })

          results.tables[tableName] = {
            exists: true,
            count: count || 0,
            sampleData: sampleError ? [] : sampleData,
            lastUpdated: sampleData?.[0]?.created_at || sampleData?.[0]?.updated_at
          }
        }
      } catch (err) {
        console.error(`🚨 检查表 ${tableName} 时出错:`, err)
        results.tables[tableName] = {
          exists: false,
          error: err instanceof Error ? err.message : '未知错误',
          count: 0
        }
      }
    }

    // 生成数据库摘要
    const existingTables = Object.keys(results.tables).filter(
      table => results.tables[table].exists
    )

    const totalRecords = Object.values(results.tables).reduce(
      (sum: number, table: any) => sum + (table.count || 0), 0
    )

    results.summary = {
      totalTables: tables.length,
      existingTables: existingTables.length,
      missingTables: tables.length - existingTables.length,
      totalRecords,
      databaseHealth: existingTables.length === tables.length ? 'healthy' : 'needs_setup'
    }

    // 生成建议
    const recommendations = []
    if (existingTables.length === 0) {
      recommendations.push('🚨 数据库未初始化，请在Supabase SQL编辑器中执行 scripts/setup-database.sql')
    } else if (existingTables.length < tables.length) {
      recommendations.push('⚠️ 部分表缺失，建议重新执行数据库初始化脚本')
    } else {
      recommendations.push('✅ 数据库结构完整')
      if (totalRecords === 0) {
        recommendations.push('💡 数据库为空，这是正常的初始状态')
      }
    }

    results.recommendations = recommendations

    return NextResponse.json({
      success: existingTables.length > 0,
      message: `数据库状态检查完成 - ${existingTables.length}/${tables.length} 表存在`,
      data: results
    })

  } catch (error) {
    console.error('❌ 数据库状态检查失败:', error)
    return NextResponse.json(
      { 
        success: false,
        error: '数据库状态检查失败',
        details: error instanceof Error ? error.message : '未知错误'
      },
      { status: 500 }
    )
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { handleCreemWebhook } from '@/lib/payment/creem'

// 🔥 通用支付Webhook处理器
export async function POST(request: NextRequest) {
  try {
    // 🔍 获取请求体和各种可能的签名头
    const body = await request.text()
    const userAgent = request.headers.get('user-agent') || ''
    const contentType = request.headers.get('content-type') || ''

    // 🔍 检测支付提供商
    const paymentProvider = detectPaymentProvider(request, body)

    console.log(`收到支付Webhook请求 - 提供商: ${paymentProvider}`)

    switch (paymentProvider) {
      case 'creem':
        return await handleCreemPayment(request, body)

      case 'stripe':
        return await handleStripePayment(request, body)

      case 'paypal':
        return await handlePayPalPayment(request, body)

      default:
        console.error('未知的支付提供商:', paymentProvider)
        return NextResponse.json(
          { 
            success: false, 
            error: `不支持的支付提供商: ${paymentProvider}` 
          },
          { status: 400 }
        )
    }

  } catch (error) {
    console.error('通用支付Webhook处理异常:', error)
    return NextResponse.json(
      { 
        success: false, 
        error: '服务器内部错误' 
      },
      { status: 500 }
    )
  }
}

// 🔍 检测支付提供商
function detectPaymentProvider(request: NextRequest, body: string): string {
  // 🔥 通过请求头检测CREEM
  const creemSignature = request.headers.get('x-creem-signature') || 
                        request.headers.get('x-signature')
  if (creemSignature) {
    return 'creem'
  }

  // 🔥 通过请求头检测Stripe
  const stripeSignature = request.headers.get('stripe-signature')
  if (stripeSignature) {
    return 'stripe'
  }

  // 🔥 通过User-Agent检测PayPal
  const userAgent = request.headers.get('user-agent') || ''
  if (userAgent.includes('PayPal')) {
    return 'paypal'
  }

  // 🔥 通过请求体内容检测
  try {
    const data = JSON.parse(body)

    // CREEM特征检测
    if (data.type && (data.type.includes('checkout') || data.type.includes('subscription'))) {
      return 'creem'
    }

    // Stripe特征检测
    if (data.object && data.object === 'event') {
      return 'stripe'
    }

    // PayPal特征检测
    if (data.event_type || data.resource_type) {
      return 'paypal'
    }
  } catch (error) {
    console.log('无法解析请求体为JSON，使用默认检测')
  }

  // 🔥 默认返回CREEM（当前主要使用的支付方式）
  return 'creem'
}

// 🔥 处理CREEM支付
async function handleCreemPayment(request: NextRequest, body: string) {
  const signature = request.headers.get('x-creem-signature') || 
                   request.headers.get('x-signature') || 
                   request.headers.get('signature') || ''

  console.log('处理CREEM支付Webhook')

  const result = await handleCreemWebhook(body, signature)

  if (result.success) {
    console.log('CREEM Webhook处理成功:', result.event?.type)
    return NextResponse.json({ 
      success: true, 
      provider: 'creem',
      message: 'CREEM Webhook处理成功',
      eventType: result.event?.type 
    })
  } else {
    console.error('CREEM Webhook处理失败:', result.error)
    return NextResponse.json(
      { 
        success: false, 
        provider: 'creem',
        error: result.error 
      },
      { status: 400 }
    )
  }
}

